var OVERLAY_MODAL = false;
/* 帮助面板：把散落在各处的键盘能力收成一张表。原来没有入口 ——
   图标库里有 help 字形却从来没接线，等于"能力存在但用户学不到"。 */
function openHelpPanel(){
  var rows = [
    ["← → 或 J K", "上一张 / 下一张卡"],
    ["Ctrl + K", "搜索（标题 + 正文）"],
    ["Esc", "关闭当前面板 / 弹层 / 只付一次退栈"],
    ["空格 / Enter", "打开当前聚焦的按钮"],
    ["终端 ↑ ↓", "翻命令历史"],
    ["终端 Tab / Ctrl + Space", "补全 / 列出候选"],
    ["终端 Shift + Enter", "换行（不执行）"]
  ];
  openModal("help", "快捷键与帮助",
    '<div class="body" style="font-size:14px;line-height:1.8">' +
      '<table class="md-table"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody>' +
      rows.map(function(r){
        return "<tr><td><kbd>" + escapeHtml(r[0]) + "</kbd></td><td>" + escapeHtml(r[1]) + "</td></tr>";
      }).join("") +
      "</tbody></table>" +
      "<p>完整说明见仓库根目录的 <code>计算概论学习终端-使用说明书.pdf</code>；" +
      "题库与课件每周会更新，顶栏「更新」里可以先查有没有新内容。</p>" +
      '<p class="asHint" style="padding:0">所有数据都在本机：讲义、课件、100 Days 副本可离线读；' +
      "AI 解析与自动提交才需要联网。</p>" +
    "</div>" +
    '<div class="hwActions"><button data-act="closemodal">知道了</button></div>');
}
